class Solution:
    def sortString(self, s: str) -> str:
        chars = list(s)
        res = []
        while chars:
            last = min(chars)
            chars.remove(last)
            res.append(last)
            while True:
                nxt = [c for c in chars if c > last]
                if not nxt:
                    break
                last = min(nxt)
                chars.remove(last)
                res.append(last)
            if not chars:
                break
            last = max(chars)
            chars.remove(last)
            res.append(last)
            while True:
                nxt = [c for c in chars if c < last]
                if not nxt:
                    break
                last = max(nxt)
                chars.remove(last)
                res.append(last)
        return ''.join(res)

