class Solution {
public:
    string sortString(string s) {
        vector<char> chars(s.begin(), s.end());
        string res;
        while (!chars.empty()) {
            auto it = min_element(chars.begin(), chars.end());
            char last = *it;
            chars.erase(it);
            res += last;
            while (true) {
                auto nxt = chars.end();
                for (auto p = chars.begin(); p != chars.end(); ++p)
                    if (*p > last && (nxt == chars.end() || *p < *nxt)) nxt = p;
                if (nxt == chars.end()) break;
                last = *nxt;
                chars.erase(nxt);
                res += last;
            }
            if (chars.empty()) break;
            auto it2 = max_element(chars.begin(), chars.end());
            last = *it2;
            chars.erase(it2);
            res += last;
            while (true) {
                auto nxt = chars.end();
                for (auto p = chars.begin(); p != chars.end(); ++p)
                    if (*p < last && (nxt == chars.end() || *p > *nxt)) nxt = p;
                if (nxt == chars.end()) break;
                last = *nxt;
                chars.erase(nxt);
                res += last;
            }
        }
        return res;
    }
};

