class Solution {
    public String sortString(String s) {
        List<Character> chars = new ArrayList<>();
        for (char c : s.toCharArray()) chars.add(c);
        StringBuilder res = new StringBuilder();
        while (!chars.isEmpty()) {
            char last = Collections.min(chars);
            chars.remove((Character) last);
            res.append(last);
            while (true) {
                Character nxt = null;
                for (char c : chars) if (c > last && (nxt == null || c < nxt)) nxt = c;
                if (nxt == null) break;
                last = nxt;
                chars.remove((Character) last);
                res.append(last);
            }
            if (chars.isEmpty()) break;
            last = Collections.max(chars);
            chars.remove((Character) last);
            res.append(last);
            while (true) {
                Character nxt = null;
                for (char c : chars) if (c < last && (nxt == null || c > nxt)) nxt = c;
                if (nxt == null) break;
                last = nxt;
                chars.remove((Character) last);
                res.append(last);
            }
        }
        return res.toString();
    }
}

