var sortString = function(s) {
    let chars = s.split('');
    let res = [];
    while (chars.length) {
        let last = Math.min(...chars.map(c => c.charCodeAt(0)));
        chars.splice(chars.indexOf(String.fromCharCode(last)), 1);
        res.push(String.fromCharCode(last));
        while (true) {
            const bigger = chars.filter(c => c.charCodeAt(0) > last).map(c => c.charCodeAt(0));
            if (!bigger.length) break;
            last = Math.min(...bigger);
            chars.splice(chars.indexOf(String.fromCharCode(last)), 1);
            res.push(String.fromCharCode(last));
        }
        if (!chars.length) break;
        last = Math.max(...chars.map(c => c.charCodeAt(0)));
        chars.splice(chars.indexOf(String.fromCharCode(last)), 1);
        res.push(String.fromCharCode(last));
        while (true) {
            const smaller = chars.filter(c => c.charCodeAt(0) < last).map(c => c.charCodeAt(0));
            if (!smaller.length) break;
            last = Math.max(...smaller);
            chars.splice(chars.indexOf(String.fromCharCode(last)), 1);
            res.push(String.fromCharCode(last));
        }
    }
    return res.join('');
};

