class Solution:
    def sortString(self, s: str) -> str:
        cnt = [0] * 26
        for c in s:
            cnt[ord(c) - ord('a')] += 1
        res = []
        n = len(s)
        while len(res) < n:
            for i in range(26):
                if cnt[i]:
                    cnt[i] -= 1
                    res.append(chr(i + ord('a')))
            for i in range(25, -1, -1):
                if cnt[i]:
                    cnt[i] -= 1
                    res.append(chr(i + ord('a')))
        return ''.join(res)

