class Solution {
public:
    string sortString(string s) {
        int cnt[26] = {0};
        for (char c : s) cnt[c - 'a']++;
        string res;
        int n = s.size();
        while ((int)res.size() < n) {
            for (int i = 0; i < 26; i++)
                if (cnt[i]) { cnt[i]--; res += ('a' + i); }
            for (int i = 25; i >= 0; i--)
                if (cnt[i]) { cnt[i]--; res += ('a' + i); }
        }
        return res;
    }
};

