        int[] cnt = new int[26];
        for (char c : s.toCharArray()) cnt[c - 'a']++;
        StringBuilder res = new StringBuilder();
        int n = s.length();
        while (res.length() < n) {
            for (int i = 0; i < 26; i++)
                if (cnt[i] > 0) { cnt[i]--; res.append((char)('a' + i)); }
            for (int i = 25; i >= 0; i--)
                if (cnt[i] > 0) { cnt[i]--; res.append((char)('a' + i)); }
        }
        return res.toString();
    }
}

